description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa 4 biển báo 'Ra khỏi khu vực' (R.E.10a, R.E.10b, R.E.10c, R.E.10d) theo QCVN 41:2024/BGTVT, dùng để chỉ dẫn hết hiệu lực của các biển cấm, hạn chế hoặc chỉ dẫn trong một khu vực.",
  "items": [
    {
      "identifier": "Biển R.E.10a",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng bên trong là biển cấm đỗ xe (hình tròn đỏ với gạch chéo) bị gạch chéo chéo từ góc trên trái xuống dưới phải.",
      "meaning_or_specification": "Biển báo 'Hết cấm đỗ xe trong khu vực' – báo hiệu kết thúc hiệu lực của biển cấm đỗ xe trong khu vực đó."
    },
    {
      "identifier": "Biển R.E.10b",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng bên trong là biển cấm đỗ xe theo giờ (hình tròn đỏ với gạch chéo và thời gian '4.00 - 18.00') bị gạch chéo chéo từ góc trên trái xuống dưới phải.",
      "meaning_or_specification": "Biển báo 'Hết cấm đỗ xe theo giờ trong khu vực' – báo hiệu kết thúc hiệu lực của biển cấm đỗ xe theo giờ trong khu vực đó."
    },
    {
      "identifier": "Biển R.E.10c",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng bên trong là biển chỉ dẫn khu vực đỗ xe (hình chữ P màu xanh dương trên nền trắng) bị gạch chéo chéo từ góc trên trái xuống dưới phải.",
      "meaning_or_specification": "Biển báo 'Hết khu vực đỗ xe' – báo hiệu kết thúc hiệu lực của biển chỉ dẫn khu vực đỗ xe trong khu vực đó."
    },
    {
      "identifier": "Biển R.E.10d",
      "visual_or_geometric_features": "Hình tròn viền đỏ, nền trắng, biểu tượng bên trong là biển hạn chế tốc độ tối đa (số '30' màu đen trên nền trắng) bị gạch chéo chéo từ góc trên trái xuống dưới phải.",
      "meaning_or_specification": "Biển báo 'Hết hạn chế tốc độ tối đa trong khu vực' – báo hiệu kết thúc hiệu lực của biển hạn chế tốc độ tối đa trong khu vực đó."
    }
  ]
}
